import{_ as i,o as p,c as t,a6 as e}from"./chunks/framework.CGCCzANv.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"readingTime":"6 min read"},"headers":[],"relativePath":"游戏引擎/游戏设计/Godot_JRPG/GJ.md","filePath":"游戏引擎/游戏设计/Godot_JRPG/GJ.md"}'),a={name:"游戏引擎/游戏设计/Godot_JRPG/GJ.md"};function r(o,l,u,s,n,_){return p(),t("div",null,[...l[0]||(l[0]=[e('<p>这是 Godot 4.6（Forward Plus） ，3D 物理引擎用的是 Jolt Physics ，Windows 渲染驱动 D3D12 ；目前只有 main.tscn 放了一个方块，适合作为“从零搭系统”的起点。</p><p>系统清单（3D JRPG 常见模块）</p><ul><li><p>基础框架</p><ul><li>游戏状态与流程：标题界面 → 读档/新游戏 → 探索 → 战斗 → 结算 → 返回探索</li><li>场景管理：加载/卸载、过场切换、出生点/传送点、异步加载（可后置）</li><li>全局服务：事件总线、资源缓存、配置与数据读取、时间缩放/暂停、调试开关</li></ul></li><li><p>探索（场景内）</p><ul><li>玩家控制器（3D CharacterBody）：移动、转向、冲刺/走路、重力/坡度、碰撞</li><li>相机系统：第三人称跟随、碰撞避障、锁定/自由视角、室内外参数</li><li>交互系统：可交互物（NPC/宝箱/门/触发器）、提示UI、交互优先级与范围判定</li><li>导航与AI（探索态）：NPC 巡逻/站立、简单避障（更复杂的可后置）</li></ul></li><li><p>战斗（JRPG 核心）</p><ul><li>战斗模式：回合制 / ATB（先按回合制做“可跑通”的垂直切片）</li><li>参战单位系统：队伍/敌人、站位/阵型（可简化为固定点位）</li><li>指令系统：普攻/技能/道具/防御/逃跑</li><li>结算系统：经验、金钱、掉落、状态清理、战后恢复规则</li></ul></li><li><p>成长与数值</p><ul><li>属性模型：HP/MP、攻击/防御、速度、命中/暴击等（先做最小集合）</li><li>等级与经验曲线：升级、属性成长、学习技能</li><li>状态效果：中毒/眩晕/增益减益、持续回合、叠加规则</li></ul></li><li><p>物品与装备</p><ul><li>背包：堆叠规则、容量规则（可先不做容量）</li><li>装备槽位：武器/防具/饰品，装备后改属性</li><li>道具效果：战斗内/外可用性、目标选择</li></ul></li><li><p>剧情与任务</p><ul><li>对话系统：文本框、头像/姓名、选项分支、触发条件</li><li>事件/过场：镜头控制、角色走位、等待/并行、脚本化事件</li><li>任务系统：接取/进度/完成、条件计数、奖励发放</li></ul></li><li><p>UI 与体验</p><ul><li>菜单系统：主菜单、队伍、装备、物品、技能、设置</li><li>HUD：交互提示、简易状态条（可选）</li><li>输入与重映射：键鼠/手柄映射、操作提示适配</li></ul></li><li><p>存档与设置</p><ul><li>存档：世界状态、队伍与数值、任务进度、开箱/开门等持久化</li><li>设置：音量、画质、控制、语言（语言可后置）</li></ul></li><li><p>音频与表现</p><ul><li>音频管理：BGM/SE、淡入淡出、场景切歌</li><li>VFX：技能特效、受击闪白、镜头震动（先做最小）</li></ul></li><li><p>工具与调试（强烈建议早做）</p><ul><li>调试面板：跳场景/加钱/加道具/强制进战、日志分级</li><li>数据校验：配置缺失、ID 冲突、引用断链检测（可逐步补） 每个系统的“要求”（建议统一成验收标准）</li></ul></li><li><p>可跑通 ：能从入口操作到结果（例如“探索→触发战斗→打完→回探索”）。</p></li><li><p>可复用 ：同类内容不复制代码（例如 20 个宝箱靠配置生成，不是 20 份脚本）。</p></li><li><p>数据驱动 ：核心内容用数据定义（角色/技能/物品/敌人/掉落），逻辑读数据执行。</p></li><li><p>可扩展 ：后续加新技能/新状态/新敌人不改旧系统或只做小改动。</p></li><li><p>可调试 ：关键流程可打印/可视化（战斗结算、伤害公式、触发器条件）。</p></li><li><p>最小依赖 ：探索系统不要强绑战斗UI；战斗系统不要依赖具体关卡脚本。 逐个构建顺序（推荐“垂直切片”路线）</p></li><li><p>第 0 阶段：项目骨架 ：场景流转 + 输入映射 + 基础UI框架 + 调试入口</p></li><li><p>第 1 阶段：探索闭环 ：玩家控制器 + 相机 + 交互（先做 NPC 对话 / 触发器 / 宝箱任意一个）</p></li><li><p>第 2 阶段：战斗闭环（最小可玩） ：遇敌触发 → 战斗场景 → 回合制指令（普攻）→ 结算 → 返回</p></li><li><p>第 3 阶段：数值与内容化 ：属性/技能/道具数据驱动 + 掉落/经验 + 敌人配置化</p></li><li><p>第 4 阶段：剧情任务与存档 ：对话分支、任务进度、存档恢复世界状态</p></li><li><p>第 5 阶段：完善体验 ：完整菜单、音频/VFX、状态效果、更多战斗指令、工具链</p></li></ul><p>地形插件<br><a href="https://github.com/TokisanGames/Terrain3D" target="_blank" rel="noreferrer">https://github.com/TokisanGames/Terrain3D</a></p>',4)])])}const m=i(a,[["render",r]]);export{c as __pageData,m as default};
